def split_test_groups(region):
    """Return list of (name, [lines...]) where lines include the section comment
    and all test blocks following it (up to the next section comment)."""
    groups = []
    current = None
    for ln in region:
        m = sec_re.match(ln)
        if m:
            current = [ln]
            groups.append((m.group(2).strip(), current))
        else:
            if current is not None:
                current.append(ln)
    # The last group extends to the end of the region, which includes the
    # closing '}' of `mod tests` — strip it (and trailing blank lines).
    last_name, last_lines = groups[-1]
    while last_lines and last_lines[-1].strip() == "":
        last_lines.pop()
    if last_lines and last_lines[-1].strip() == "}":
        last_lines.pop()
    while last_lines and last_lines[-1].strip() == "":
        last_lines.pop()
    # Trim trailing blank lines from every group (assembly re-adds single blanks).
    for _, g in groups:
        while g and g[-1].strip() == "":
            g.pop()
    return groups

