    and all test blocks following it (up to the next section comment)."""
    groups = []
    current = None
    for ln in region:
        m = sec_re.match(ln)
        if m:
            current = [ln]
            groups.append((m.group(2).strip(), current))
        else:
            if current is not None:
                current.append(ln)
    return groups

